type HmacSha256 = Hmac<Sha256>;
type AppState = Arc<App>;
type Fields = HashMap<String, String>;
type Result<T> = std::result::Result<T, AppError>;

struct App {
    db: Mutex<Connection>,
    secret: String,
    credential_signature: Vec<u8>,
    csrf: String,
}

impl App {
    fn db(&self) -> Result<MutexGuard<'_, Connection>> {
        self.db
            .lock()
            .map_err(|_| AppError::Internal("Database lock poisoned".into()))
    }
    fn check_csrf(&self, fields: &Fields) -> Result<()> {
        let token = URL_SAFE_NO_PAD
            .decode(field(fields, "csrf"))
            .map_err(|_| AppError::Forbidden)?;
        let mut mac = HmacSha256::new_from_slice(self.secret.as_bytes()).unwrap();
        mac.update(b"quizzy moderator csrf v1");
        mac.verify_slice(&token).map_err(|_| AppError::Forbidden)
    }
}

#[derive(Debug)]
enum AppError {
    NotFound,
    Forbidden,
    BadRequest,
    Internal(String),
}
impl From<rusqlite::Error> for AppError {
    fn from(error: rusqlite::Error) -> Self {
        Self::Internal(error.to_string())
    }
}
impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            Self::NotFound => (StatusCode::NOT_FOUND, "Page not found"),
            Self::Forbidden => (
                StatusCode::FORBIDDEN,
                "Invalid form token. Reload the page and try again.",
            ),
            Self::BadRequest => (StatusCode::BAD_REQUEST, "Invalid request"),
            Self::Internal(error) => {
                eprintln!("Application error: {error}");
                (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    "Something went wrong. Please try again.",
                )
            }
        };
        (
            status,
            Html(views::page(
                message,
                &format!("<h2>{message}</h2><a href=\"/moderate\">All quizzes</a>"),
            )),
        )
            .into_response()
    }
}

fn signature(secret: &str, message: &[u8]) -> Vec<u8> {
    let mut mac = HmacSha256::new_from_slice(secret.as_bytes()).unwrap();
    mac.update(message);
    mac.finalize().into_bytes().to_vec()
}

