use std::fmt::Write;

pub fn escape(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

pub fn page(title: &str, content: &str) -> String {
    format!(
        r#"<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{} · Quizzy</title><link rel="stylesheet" href="/assets/quizzy.css"><link rel="stylesheet" href="/assets/app.css"><script src="/assets/app.js" defer></script></head><body><header class="admin-header"><a href="/moderate" class="logo admin-header__logo"><span class="logo__mark">?</span>Quizzy</a><span class="admin-header__tag">Moderator</span></header><main class="admin-main">{}</main></body></html>"#,
        escape(title),
        content
    )
}

pub fn token(csrf: &str) -> String {
    format!(r#"<input type="hidden" name="csrf" value="{csrf}">"#)
}

fn errors(messages: &[&str]) -> String {
    if messages.is_empty() {
        return String::new();
    }
    let mut html = String::from(r#"<div class="errors" role="alert"><ul>"#);
    for message in messages {
        write!(html, "<li>{}</li>", escape(message)).unwrap();
    }
    html.push_str("</ul></div>");
    html
}

pub fn quiz_list(quizzes: &[(i64, String, usize, usize)]) -> String {
    let mut html = String::from(
        r#"<div class="page-head"><h1>Quizzes</h1><a class="btn btn--pink" href="/moderate/quizzes/new">New quiz</a></div>"#,
    );
    if quizzes.is_empty() {
        html.push_str(r#"<div class="empty"><h3>Your next great quiz starts here</h3><p>Create a quiz, then add questions for your audience.</p></div>"#);
    } else {
        html.push_str(r#"<ul class="quiz-list">"#);
        for (id, title, total, active) in quizzes {
            write!(html, r#"<li class="card"><a class="quiz-tile" href="/moderate/quizzes/{id}"><h3>{}</h3><div class="meta">{active} of {total} questions active</div></a></li>"#, escape(title)).unwrap();
        }
        html.push_str("</ul>");
    }
    page("Quizzes", &html)
}

pub fn quiz_form(id: Option<i64>, title: &str, csrf: &str, messages: &[&str]) -> String {
    let heading = if id.is_some() {
        "Quiz settings"
    } else {
        "New quiz"
