    let mut stmt = db.prepare("SELECT q.id, q.title, COUNT(s.id), COALESCE(SUM(s.active), 0) FROM quizzes q LEFT JOIN questions s ON s.quiz_id = q.id GROUP BY q.id ORDER BY q.id DESC")?;
